x = Symbol('x')

def nolim_at(N, D, a):
    """N/D 의 x->a 극한이 (유한값으로) 존재하지 않으면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    if Dp.is_zero:
        return True
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.eval(a) == 0

def all_ok(N, D):
    """모든 실수 a 에서 극한이 존재하면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.count_roots() == 0

def ks():
    out = []
    for k in range(-20, 21):
        N = (x - 1)*(x - 3)*(x - 5)*(x - 7)
        D = x**2 - 2*k*x + 2*k - 1
        if all_ok(N, D):
            out.append(k)
    return out

def skill():
    return sum(k for k in [2, 3, 4] if 2*k - 1 in (3, 5, 7))

def standard():
    return sum(ks())

def unique():
    return [standard()]
